INSERT  IGNORE INTO `product` (`id`,`active`,`created_at`,`description`,`image`,`meta_description`,`meta_title`,`name`,`price`,`short_description`,`slug`,`updated_at`,`ole_price`,`sold`,`weight`) VALUES (31,0x01,'2026-03-14 22:07:23.018063','','http://res.cloudinary.com/dt2g4oabz/image/upload/v1773500839/iypozhuuhadazdzfs8on.jpg','Tốc độ hơn với X30. Bám dính siêu tốt','ADIDAS X30','ADIDAS X30',200000,NULL,'adidas-x30','2026-05-16 19:52:53.697790',350000,2,0.5),(32,0x01,'2026-03-16 19:50:18.721817','<p>Trả g&oacute;p dễ d&agrave;ng c&ugrave;ng Fundiin &mdash; Đa dạng thương hiệu. Lu&ocirc;n cập nhật mẫu m&atilde; mới. Nhiều phụ kiện&nbsp;<em>b&oacute;ng đ&aacute;</em>&nbsp;ch&iacute;nh h&atilde;ng. Mua ngay. Gi&uacute;p bạn thỏa m&atilde;n đam m&ecirc; s&acirc;n cỏ c&ugrave;ng c&aacute;c sản phẩm&nbsp;<em>gi&agrave;y đ&aacute; b&oacute;ng</em>&nbsp;ch&iacute;nh h&atilde;ng chất lượng nhất.</p>','http://res.cloudinary.com/dt2g4oabz/image/upload/v1773665415/ot3adtsyjlk77akxlxiv.jpg','Bám sân tốt, không bong chóc. phù hợp đá sân cỏ tự nhiên, sân nhân tạo.','NIKE Donimo B40','NIKE Donimo B40',200000,NULL,'nike-donimo-b40','2026-03-16 19:50:18.733769',350000,0,0.5),(33,0x01,'2026-03-16 20:03:14.339387','','http://res.cloudinary.com/dt2g4oabz/image/upload/v1773666190/xtfvoshavbluvonupwot.jpg','','NIKE Donimo B52','NIKE Donimo B52',200000,NULL,'nike-donimo-b52','2026-03-16 20:03:14.339386',350000,0,0.5),(35,0x01,'2026-03-16 20:06:14.676221','','http://res.cloudinary.com/dt2g4oabz/image/upload/v1773666371/buvumiwj4imkwvivheh2.jpg','','JOMA 2025 X12','JOMA 2025 X12',500000,NULL,'joma-2025-x12','2026-03-16 20:06:14.676220',100000,0,0.5),(36,0x01,'2026-03-16 20:08:42.235171','<p>M&ugrave;a giải mới đang đến gần v&agrave; Nike đ&atilde; sẵn s&agrave;ng \"thổi b&ugrave;ng\" tinh thần thi đấu của c&aacute;c cầu thủ với bộ sưu tập&nbsp;<strong>\"Mad Ambition\" Pack</strong>&nbsp;đầy ấn tượng. Lấy cảm hứng từ kh&aacute;t vọng chinh phục m&atilde;nh liệt, Nike đ&atilde; kho&aacute;c&nbsp;l&ecirc;n những đ&ocirc;i gi&agrave;y đ&igrave;nh đ&aacute;m như Air Zoom Mercurial, Phantom v&agrave; Tiempo những m&agrave;u sắc xanh đầy sức sống, hứa hẹn mang đến trải nghiệm thi đấu đỉnh cao cho c&aacute;c ng&ocirc;i sao s&acirc;n cỏ.</p>\n<p>Mẫu gi&agrave;y được mệnh danh l&agrave; \"Best Seller\" của nh&agrave; Nike tại thị trường Việt Nam. Mỗi đợt ph&aacute;t h&agrave;nh lu&ocirc;n tạo n&ecirc;n sức h&uacute;t cực kỳ lớn.&nbsp;</p>','http://res.cloudinary.com/dt2g4oabz/image/upload/v1773666519/sbvl4pasli4iuv4r3rcd.png','','WIKA A20 Siêu Phẩm','WIKA A20 Siêu Phẩm',350000,NULL,'wika-a20-sieu-pham','2026-05-16 19:50:17.610133',500000,1,0.5),(37,0x01,'2026-03-16 21:33:40.083003','','http://res.cloudinary.com/dt2g4oabz/image/upload/v1773671617/xodmpdzxmghggxak1bbj.jpg','','ADIDAS','ADIDAS',200000,NULL,'adidas','2026-05-16 19:50:17.614281',350000,1,0.5),(38,0x01,'2026-05-03 00:19:41.071423','','http://res.cloudinary.com/dt2g4oabz/image/upload/v1777742377/jnx0szkiaxitxkddkvvm.jpg','','Nemeziz','Nemeziz',1500000,NULL,'nemeziz','2026-05-03 00:19:41.072418',1950000,0,0.2),(39,0x01,'2026-05-03 00:20:54.496482','','http://res.cloudinary.com/dt2g4oabz/image/upload/v1777742449/wki3rhlavnenqfrx9auf.webp','','Predator Edge+ Firm Ground Boots HR1560','Predator Edge+ Firm Ground Boots HR1560',6300000,NULL,'predator-edge-firm-ground-boots-hr1560','2026-05-16 19:50:17.615279',7500000,1,0.26),(40,0x01,'2026-05-03 00:21:59.449898','','http://res.cloudinary.com/dt2g4oabz/image/upload/v1777742516/wc3ycue9jqcb6g71rluz.jpg','','X Speedportal.3 TF Beyond Fast Pack GW8486','X Speedportal.3 TF Beyond Fast Pack GW8486',1650000,NULL,'x-speedportal3-tf-beyond-fast-pack-gw8486','2026-05-16 19:50:17.616282',1950000,1,0.21),(41,0x01,'2026-05-03 00:24:38.067428','','http://res.cloudinary.com/dt2g4oabz/image/upload/v1777742672/yfh6f6pnvnc6aafigfyl.jpg','','Predator Freak.3 Low TF Superspectral FW7520','Predator Freak.3 Low TF Superspectral FW7520',1890000,NULL,'predator-freak3-low-tf-supe